async ({ workspace: { read, edit } }) => {
  const file = "test/extension/raw-grammar-call.test.ts";
  const r = await read(file);
  const rows = r.content.split("\n").map((l) => { const k = l.indexOf("|"); return { a: l.slice(0, k), t: l.slice(k + 1) }; });
  const drop = [
    "shows the same @pit label and params from a persisted raw call after reload",
    "updates the displayed label when a completed source changes",
    "does not reuse cached options when another argument is added",
    "updates a streaming header when the same call becomes complete",
    "keeps unfinished source options as received while a call is streaming",
    "shows the coerced options that Pi will actually execute",
    "keeps $name visible in the original source",
  ];
  const starts = rows.map((l, i) => (/^ {2}it(\.each)?[(<]/.test(l.t) ? i : -1)).filter((i) => i >= 0);
  const changes: { kind: "delete"; start: string; end: string }[] = [];
  for (const name of drop) {
    const idx = rows.findIndex((l) => l.t.includes(name));
    const start = Math.max(...starts.filter((s) => s <= idx));
    const next = starts.find((s) => s > idx);
    if (idx < 0 || next === undefined) throw new Error(name);
    changes.push({ kind: "delete", start: rows[start].a, end: rows[next - 1].a });
  }
  await edit(file, { revision: r.revision, changes });
  const after = await read(file, { format: "raw" });
  return after.content.split("\n").filter((l) => /^ {2}it/.test(l));
}
